#!/usr/bin/env python3
"""Import the full, licensed Scott Buckley collection from the publisher."""
import hashlib,json,pathlib,shutil,subprocess,tempfile,urllib.request
ROOT=pathlib.Path(__file__).resolve().parents[1]
WEB=ROOT/'src/MichelsLife/frontend/assets/audio/classical'
RAW=ROOT/'android/app/src/main/res/raw'
SOURCES=json.loads("[{\"id\":\"sb_meanwhile\",\"title\":\"Meanwhile\",\"group\":\"ambient\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/meanwhile/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2025/01/Meanwhile.mp3\"},{\"id\":\"sb_moonlight\",\"title\":\"Moonlight\",\"group\":\"ambient\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/moonlight/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2022/07/Moonlight.mp3\"},{\"id\":\"sb_cobalt\",\"title\":\"Cobalt\",\"group\":\"ambient\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/cobalt/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2017/11/sb_cobalt.mp3\"},{\"id\":\"sb_skyward\",\"title\":\"Skyward\",\"group\":\"ambient\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/skyward/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2018/05/sb_skyward.mp3\"},{\"id\":\"sb_life_is\",\"title\":\"Life Is\",\"group\":\"ambient\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/life-is/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2017/10/sb_lifeis.mp3\"},{\"id\":\"sb_first_snow\",\"title\":\"First Snow\",\"group\":\"ambient\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/first-snow/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2022/12/FirstSnow.mp3\"},{\"id\":\"sb_midsommar\",\"title\":\"Midsommar\",\"group\":\"ambient\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/midsommar/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2020/08/sb_midsommar.mp3\"},{\"id\":\"sb_at_the_end_of_all_things\",\"title\":\"At The End Of All Things\",\"group\":\"ambient\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/at-the-end-of-all-things/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2024/06/AtTheEndOfAllThings.mp3\"},{\"id\":\"sb_in_this_moment\",\"title\":\"In This Moment\",\"group\":\"ambient\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/in-this-moment/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2026/08/InThisMoment.mp3\"},{\"id\":\"sb_hyperion\",\"title\":\"Hyperion\",\"group\":\"cinematic\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/hyperion/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2024/06/Hyperion.mp3\"},{\"id\":\"sb_ascension\",\"title\":\"Ascension\",\"group\":\"cinematic\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/ascension/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2019/02/sb_ascension.mp3\"},{\"id\":\"sb_bring_me_the_sky\",\"title\":\"Bring Me The Sky\",\"group\":\"cinematic\",\"performer\":\"Scott Buckley\",\"license\":\"CC BY 4.0\",\"license_url\":\"https://creativecommons.org/licenses/by/4.0/\",\"source_page\":\"https://www.scottbuckley.com.au/library/bring-me-the-sky/\",\"url\":\"https://www.scottbuckley.com.au/library/wp-content/uploads/2021/10/sb_bringmethesky.mp3\"}]")
def duration(p):
    d=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_streams','-show_format','-of','json',str(p)]))
    if not any(s['codec_type']=='audio' for s in d['streams']): raise ValueError('not audio')
    return float(d['format']['duration'])
def main():
    manifest=[]
    with tempfile.TemporaryDirectory() as temp:
        temp=pathlib.Path(temp)
        for item in SOURCES:
            id=item['id']; original=temp/(id+'.source.mp3'); target=temp/(id+'.mp3')
            request=urllib.request.Request(item['url'],headers={'User-Agent':'MichelsLife/1.0 (licensed audio; github.com/michels-lab/michel-s-life)'})
            with urllib.request.urlopen(request,timeout=120) as response:
                if not response.geturl().startswith('https://www.scottbuckley.com.au/'): raise ValueError('unexpected origin')
                data=response.read(40000001)
                if not 100000<len(data)<=40000000: raise ValueError('unexpected media size')
                original.write_bytes(data)
            seconds=duration(original)
            if not 30<seconds<1800: raise ValueError('unexpected full track duration')
            subprocess.run(['ffmpeg','-v','error','-i',str(original),'-map','0:a:0','-c:a','libmp3lame','-b:a','96k','-ar','44100','-metadata','title='+item['title'],'-metadata','artist=Scott Buckley','-metadata','copyright=CC BY 4.0 https://creativecommons.org/licenses/by/4.0/',str(target)],check=True)
            if abs(duration(target)-seconds)>.5: raise ValueError('truncated track')
            record={**item,'source_sha256':hashlib.sha256(data).hexdigest(),'asset_sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'duration_seconds':duration(target),'modifications':'MP3 bitrate conversion only; full track; no synthesis or edits'}
            manifest.append(record);print('VERIFIED',id,seconds,record['asset_sha256'],flush=True)
        WEB.mkdir(parents=True,exist_ok=True)
        for item in manifest:
            id=item['id'];shutil.copy2(temp/(id+'.mp3'),WEB/(id+'.mp3'));shutil.copy2(temp/(id+'.mp3'),RAW/('mlv_focus_'+id+'.mp3'))
        (WEB/'LIBRARY.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
if __name__=='__main__': main()
